//go:build windows

// lnk_windows.go：开始菜单 `.lnk` 枚举 + 解析（对照 voke-sys/src/apps.rs 的
// enum_shortcuts / resolve_all_inner）。
//
// 为什么需要它：mygo 的 `Shell.InstalledApps` 只返回本地化显示名（「服务」）+
// AUMID/相对路径，没有英文名/描述/目标；`Microsoft.AutoGenerated.*` 条目（任务
// 管理器）连英文文件名都没有。Rust 版靠额外枚举开始菜单 `.lnk`（英文文件名/描述）
// 才能用 service/regedit/task 搜到。本文件补这一来源。
//
// 只解析出**显示名与 `.lnk` 本体路径**：启动时把 `.lnk` 交 shell 执行（与 Rust
// lnk_path 同款），参数/工作目录/图标由 shell 解析，故不读。
//
// COM 细节（对照 windows-0.57 生成绑定核实）：
//   - CLSID_ShellLink  {00021401-0000-0000-C000-000000000046}
//   - IID_IShellLinkW  {000214F9-0000-0000-C000-000000000046}
//   - IID_IPersistFile {0000010B-0000-0000-C000-000000000046}
//   - IShellLinkW: GetPath=槽3、GetDescription=槽6（IUnknown 占 0..2）
//   - IPersistFile: Load=槽5（IUnknown 0..2、GetClassID=3、IsDirty=4）
package platform

import (
	"log"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"syscall"
	"unsafe"

	"github.com/zyition/voke/poc/voke-go/internal/logic/appsmodel"
)

const (
	coinitApartmentThreaded = 0x2
	stgmRead                = 0x0
	slgpRawPath             = 0x4
	hresultChangedMode      = 0x80010106 // RPC_E_CHANGED_MODE：线程已以 MTA 初始化
)

// CLSID_ShellLink / IID_IShellLinkW / IID_IPersistFile（windows crate 已核实）。
var (
	clsidShellLink = syscall.GUID{Data1: 0x00021401, Data2: 0, Data3: 0,
		Data4: [8]byte{0xC0, 0, 0, 0, 0, 0, 0, 0x46}}
	iidIShellLinkW = syscall.GUID{Data1: 0x000214F9, Data2: 0, Data3: 0,
		Data4: [8]byte{0xC0, 0, 0, 0, 0, 0, 0, 0x46}}
	iidIPersistFile = syscall.GUID{Data1: 0x0000010B, Data2: 0, Data3: 0,
		Data4: [8]byte{0xC0, 0, 0, 0, 0, 0, 0, 0x46}}
)

// shellLinkVtbl 是 IShellLinkW 的 vtable 布局（IUnknown 0..2 之后按声明序）。
type shellLinkVtbl struct {
	queryInterface uintptr
	addRef         uintptr
	release        uintptr
	getPath        uintptr
	getIDList      uintptr
	setIDList      uintptr
	getDescription uintptr
}

// persistFileVtbl 是 IPersistFile 的 vtable 布局（IPersist::GetClassID 在 3）。
type persistFileVtbl struct {
	queryInterface uintptr
	addRef         uintptr
	release        uintptr
	getClassID     uintptr
	isDirty        uintptr
	load           uintptr
}

// startMenuDirs 返回两个开始菜单 Programs 目录（全用户在前，去重优先保留）。
func startMenuDirs() []string {
	const tail = `Microsoft\Windows\Start Menu\Programs`
	var dirs []string
	if pd := os.Getenv("ProgramData"); pd != "" {
		dirs = append(dirs, filepath.Join(pd, tail))
	}
	if ad := os.Getenv("APPDATA"); ad != "" {
		dirs = append(dirs, filepath.Join(ad, tail))
	}
	return dirs
}

// ShortcutApps 枚举开始菜单 .lnk 并解析成应用条目（Path = .lnk 本体，ID 为空）。
// 用单线程套间：整段锁定 OS 线程并 CoInitializeEx(STA)——loader 在独立 goroutine
// 里跑，不锁线程会跨线程用 COM。
func ShortcutApps() []appsmodel.AppEntry {
	dirs := startMenuDirs()
	if len(dirs) == 0 {
		return nil
	}
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()

	hr, _, _ := procCoInitEx.Call(0, coinitApartmentThreaded)
	inited := hr == 0 || hr == 1 // S_OK / S_FALSE
	if !inited && uint32(hr) != hresultChangedMode {
		log.Printf("voke：.lnk 枚举 CoInitializeEx 失败 0x%08x，跳过开始菜单", uint32(hr))
		return nil
	}
	if inited {
		defer ole32.NewProc("CoUninitialize").Call()
	}

	var obj unsafe.Pointer
	if r, _, _ := procCoCreateInst.Call(
		uintptr(unsafe.Pointer(&clsidShellLink)), 0, uintptr(clsctxInprocServer),
		uintptr(unsafe.Pointer(&iidIShellLinkW)), uintptr(unsafe.Pointer(&obj)),
	); r != sOK || obj == nil {
		log.Printf("voke：创建 IShellLink 失败 hr=0x%08x", uint32(r))
		return nil
	}
	sl := *(**shellLinkVtbl)(obj)
	defer syscall.Syscall(sl.release, 1, uintptr(obj), 0, 0)

	var pfObj unsafe.Pointer
	if r, _, _ := syscall.Syscall(sl.queryInterface, 3,
		uintptr(obj),
		uintptr(unsafe.Pointer(&iidIPersistFile)),
		uintptr(unsafe.Pointer(&pfObj)),
	); r != sOK || pfObj == nil {
		log.Printf("voke：QueryInterface(IPersistFile) 失败 hr=0x%08x", uint32(r))
		return nil
	}
	pf := *(**persistFileVtbl)(pfObj)
	defer syscall.Syscall(pf.release, 1, uintptr(pfObj), 0, 0)

	out := make([]appsmodel.AppEntry, 0, 128)
	seen := make(map[string]struct{})
	pathBuf := make([]uint16, 4096)
	descBuf := make([]uint16, 1024)

	for _, root := range dirs {
		_ = filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
			if err != nil || d == nil || d.IsDir() {
				return nil // 目录不可读 / 子目录：尽力而为
			}
			if !strings.EqualFold(filepath.Ext(path), ".lnk") {
				return nil
			}
			rel, rerr := filepath.Rel(root, path)
			if rerr != nil {
				rel = path
			}
			key := strings.ToLower(rel)
			if _, dup := seen[key]; dup {
				return nil // 全用户已收录同相对路径：保留更稳定的那份
			}
			seen[key] = struct{}{}

			name, target, ok := resolveShortcut(obj, pfObj, pf, path, pathBuf, descBuf)
			if !ok {
				return nil
			}
			existsDir := false
			if target != "" && !strings.HasPrefix(target, "shell:") {
				if fi, statErr := os.Stat(target); statErr == nil && fi.IsDir() {
					existsDir = true
				}
			}
			if !appsmodel.LaunchableTarget(target, existsDir) {
				log.Printf("voke：剔除不可启动的快捷方式 %s（target=%q）", path, target)
				return nil
			}
			out = append(out, appsmodel.AppEntry{Name: name, Path: path, Target: target})
			return nil
		})
	}
	return out
}

// resolveShortcut 解析一个 .lnk：Load → GetPath(RAWPATH) / GetDescription。
func resolveShortcut(shellLink, pfObj unsafe.Pointer, pf *persistFileVtbl, lnkPath string, pathBuf, descBuf []uint16) (name, target string, ok bool) {
	p, err := syscall.UTF16PtrFromString(lnkPath)
	if err != nil {
		return "", "", false
	}
	if r, _, _ := syscall.Syscall(pf.load, 3,
		uintptr(pfObj), uintptr(unsafe.Pointer(p)), stgmRead,
	); r != sOK {
		return "", "", false
	}
	sl := *(**shellLinkVtbl)(shellLink)
	for i := range pathBuf {
		pathBuf[i] = 0
	}
	if r, _, _ := syscall.Syscall6(sl.getPath, 5,
		uintptr(shellLink),
		uintptr(unsafe.Pointer(&pathBuf[0])), uintptr(len(pathBuf)),
		0, slgpRawPath, 0,
	); r == sOK {
		target = syscall.UTF16ToString(pathBuf)
	}
	for i := range descBuf {
		descBuf[i] = 0
	}
	desc := ""
	if r, _, _ := syscall.Syscall(sl.getDescription, 3,
		uintptr(shellLink),
		uintptr(unsafe.Pointer(&descBuf[0])), uintptr(len(descBuf)),
	); r == sOK {
		desc = syscall.UTF16ToString(descBuf)
	}
	stem := strings.TrimSuffix(filepath.Base(lnkPath), filepath.Ext(lnkPath))
	name = appsmodel.ShortcutName(desc, stem)
	if name == "" {
		return "", "", false
	}
	return name, target, true
}
